.gallery { list-style:none;margin:0;padding:0; display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 16px; }
.gallery__thumb { padding: 0; border: 0; border-radius: 8px; overflow: hidden; cursor: pointer; aspect-ratio: 4 / 3; }
.gallery__thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.gallery__thumb:focus-visible { outline: 2px solid #1d4ed8; outline-offset: 2px; }
.gallery__lightbox { border: 0; border-radius: 12px; padding: 16px; max-width: 90vw; max-height: 90vh; background: #121212; color: #f5f5f5; }
.gallery__lightbox::backdrop { background: rgba(0,0,0,.72); }
.gallery__full { max-width: 80vw; max-height: 70vh; display: block; margin: 0 auto; }
.gallery__counter { margin: 0 0 8px; font-size: 14px; line-height: 20px; text-align: center; }
.gallery__controls { display: flex; justify-content: center; gap: 16px; margin-top: 16px; }
.gallery__controls button { min-width: 44px; min-height: 44px; border: 1px solid #f5f5f5; border-radius: 8px; background: transparent; color: #f5f5f5; font-size: 20px; cursor: pointer; }
.gallery__controls button:focus-visible { outline: 2px solid #f5f5f5; outline-offset: 2px; }
